class Solution {
public:
    long long beautifulSubarrays(vector<int>& nums) {
        unordered_map<int, long long> cnt;
        cnt[0] = 1;
        int x = 0; long long ans = 0;
        for (int v : nums) {
            x ^= v;
            ans += cnt[x]++;
        }
        return ans;
    }
};

c.java:
class Solution {
    public long beautifulSubarrays(int[] nums) {
        Map<Integer, Long> cnt = new HashMap<>();
        cnt.put(0, 1L);
        int x = 0; long ans = 0;
        for (int v : nums) {
            x ^= v;
            ans += cnt.merge(x, 1L, Long::sum) - 1;
        }
        return ans;
    }
}

