var beautifulSubarrays = function(nums) {
    const cnt = new Map([[0, 1]]);
    let x = 0, ans = 0;
    for (const v of nums) {
        x ^= v;
        ans += cnt.get(x) || 0;
        cnt.set(x, (cnt.get(x) || 0) + 1);
    }
    return ans;
};
